#!/usr/bin/env bash
# Generated by Claude.
# Cross-compile a kernel for the UNVR (Annapurna Labs Alpine V2)
# from Alpine's linux-lts aarch64 config, with the Annapurna PCIe driver
# enabled, and wrap it as a U-Boot legacy uImage.
#
# Run as your normal user on your Arch Install:   ./build-kernel.sh
#
# Needs: aarch64-linux-gnu-gcc base-devel bc flex bison openssl libelf
#        cpio xz curl uboot-tools(mkimage)
#   sudo pacman -S --needed aarch64-linux-gnu-gcc base-devel bc flex bison openssl libelf cpio xz uboot-tools
set -euo pipefail

### --- settings (override via environment) ---------------------------------
KVER="${KVER:-6.18.58}"                         # upstream kernel version
KLOCALVERSION="${KLOCALVERSION:-${LOCALVERSION:--unvr}}"
# The kernel's own Makefile appends $LOCALVERSION from the environment on top of
# CONFIG_LOCALVERSION, which doubles the suffix (6.18.58-unvr-unvr).  Only set it in .config.
unset LOCALVERSION
CONFIG_URL="${CONFIG_URL:-https://raw.githubusercontent.com/alpinelinux/aports/master/main/linux-lts/lts.aarch64.config}"
WORK="${WORK:-$HOME/unvr-kernel}"
TFTP_DIR="${TFTP_DIR:-$HOME/tftp}"
LOADADDR="${LOADADDR:-0x30000000}"              # must stay clear of ramoops @0x12000000
JOBS="${JOBS:-$(nproc)}"
AL_ETH_DIR="${AL_ETH_DIR:-}"                    # path to al_eth-6.18 to build the Ethernet driver too
### --------------------------------------------------------------------------

export ARCH=arm64
export CROSS_COMPILE=aarch64-linux-gnu-

die() { echo "ERROR: $*" >&2; exit 1; }
for t in ${CROSS_COMPILE}gcc make bc flex bison curl tar xz mkimage; do
    command -v "$t" >/dev/null || die "missing tool: $t"
done

mkdir -p "$WORK" "$TFTP_DIR"
cd "$WORK"

SRC="linux-$KVER"
if [ ! -d "$SRC" ]; then
    echo ">>> Download linux-$KVER"
    MAJOR="${KVER%%.*}"
    curl -fLO "https://cdn.kernel.org/pub/linux/kernel/v${MAJOR}.x/linux-$KVER.tar.xz"
    tar -xf "linux-$KVER.tar.xz"
fi
cd "$SRC"

if [ ! -f .config ] || [ "${RECONFIG:-0}" = 1 ]; then
    echo ">>> Fetch Alpine lts aarch64 config"
    curl -fsSL "$CONFIG_URL" -o .config || die "could not download kernel config from $CONFIG_URL"
    S=./scripts/config
    # Board support
    $S -e ARCH_ALPINE -e PCI_MSI -e PCIE_DW_HOST -e PCIE_AL -e PCI_HOST_GENERIC -e ALPINE_MSI
    # PHY drivers for the RGMII port's external PHY (loaded before al_eth via softdep)
    $S -e PHYLIB -m MARVELL_PHY -m REALTEK_PHY
    # Let the kernel load .ko.gz itself (BusyBox modprobe hands it the compressed file first)
    $S -e MODULE_DECOMPRESS
    # Built in so the kernel can mount root from a SATA SSD without an initramfs
    $S -e SCSI -e BLK_DEV_SD -e ATA -e SATA_HOST -e SATA_AHCI -e EXT4_FS
    # Board I2C (Synopsys DesignWare) -> PCA9546 mux -> S35390A RTC + ADT7475 fan/temp,
    # plus the PCA9575 GPIO expanders for drive-bay power and LEDs
    $S -m I2C_DESIGNWARE_CORE -m I2C_DESIGNWARE_PLATFORM -m I2C_MUX_PCA954x \
       -m RTC_DRV_S35390A -m GPIO_PCA953X -m SENSORS_ADT7475 -m SENSORS_DRIVETEMP
    $S -e SERIAL_8250 -e SERIAL_8250_CONSOLE -e SERIAL_OF_PLATFORM
    # The vendor DT has an empty /hypervisor node that crashes Xen detection
    $S -d XEN
    # Handy: expose the config at /proc/config.gz
    $S -e IKCONFIG -e IKCONFIG_PROC
    # Build-environment fixes: no pahole/BTF, self-generated module signing key
    $S -d DEBUG_INFO_BTF
    $S --set-str SYSTEM_TRUSTED_KEYS ""
    $S --set-str MODULE_SIG_KEY "certs/signing_key.pem"
    $S --set-str LOCALVERSION "$KLOCALVERSION"
    $S -d LOCALVERSION_AUTO
    make olddefconfig
fi

grep -q '^CONFIG_PCIE_AL=y' .config || die "CONFIG_PCIE_AL did not stick (check dependencies with: make menuconfig)"
grep -q '^CONFIG_ARCH_ALPINE=y' .config || { ./scripts/config -e ARCH_ALPINE -e ALPINE_MSI; make olddefconfig; }
# Reboot: the Alpine SoC resets through the SP805 watchdog (wdt0); its mainline
# driver registers the restart handler.  Built in so reboot always works.
if ! grep -q '^CONFIG_ARM_SP805_WATCHDOG=y' .config; then
    ./scripts/config -e WATCHDOG -e ARM_SP805_WATCHDOG
    make olddefconfig
fi
# Root on the internal eMMC: it sits behind an ASMedia xHCI controller on the external
# PCIe bus, so USB host + mass storage must be built in (no initramfs).
if ! grep -q '^CONFIG_USB_STORAGE=y' .config || ! grep -q '^CONFIG_USB_XHCI_PCI=y' .config; then
    ./scripts/config -e USB_SUPPORT -e USB -e USB_PCI -e USB_XHCI_HCD -e USB_XHCI_PCI \
                     -e USB_STORAGE -e USB_UAS
    make olddefconfig
fi
grep -q '^CONFIG_USB_STORAGE=y' .config || die "CONFIG_USB_STORAGE is not built in"
# Storage must be built in to mount root from SATA without an initramfs
if ! grep -q '^CONFIG_SATA_AHCI=y' .config || ! grep -q '^CONFIG_EXT4_FS=y' .config; then
    ./scripts/config -e SCSI -e BLK_DEV_SD -e ATA -e SATA_HOST -e SATA_AHCI -e EXT4_FS -e MODULE_DECOMPRESS
    make olddefconfig
fi
grep -q '^CONFIG_SATA_AHCI=y' .config || die "CONFIG_SATA_AHCI is not built in"
./scripts/config --set-str LOCALVERSION "$KLOCALVERSION"

echo ">>> Build (Image + modules) with -j$JOBS"
make -j"$JOBS" Image modules

KREL=$(make -s kernelrelease)
MODOUT="$WORK/modules-$KREL"
echo ">>> Install modules to $MODOUT"
rm -rf "$MODOUT"
make -s INSTALL_MOD_PATH="$MODOUT" INSTALL_MOD_STRIP=1 modules_install
if [ -n "$AL_ETH_DIR" ]; then
    echo ">>> Build al_eth from $AL_ETH_DIR"
    [ -f "$AL_ETH_DIR/Kbuild" ] || die "AL_ETH_DIR has no Kbuild: $AL_ETH_DIR"
    make -j"$JOBS" M="$AL_ETH_DIR" modules
    make -s M="$AL_ETH_DIR" INSTALL_MOD_PATH="$MODOUT" INSTALL_MOD_STRIP=1 modules_install
    depmod -b "$MODOUT" "$KREL"
fi
rm -f "$MODOUT/lib/modules/$KREL/build" "$MODOUT/lib/modules/$KREL/source"

echo ">>> Wrap uImage"
[ -f "$TFTP_DIR/uImage" ] && cp -f "$TFTP_DIR/uImage" "$TFTP_DIR/uImage.prev"
mkimage -A arm64 -O linux -T kernel -C none -a "$LOADADDR" -e "$LOADADDR" \
    -n "Linux $KREL" -d arch/arm64/boot/Image "$TFTP_DIR/uImage" >/dev/null
chmod 644 "$TFTP_DIR/uImage"

grep -qa "amazon,al-alpine-v2-pcie" arch/arm64/boot/Image \
    && echo "    pcie-al driver: present" || echo "    WARNING: pcie-al compatible not found in Image"

echo
echo ">>> Done."
echo "    Kernel:  $TFTP_DIR/uImage  (previous saved as uImage.prev)"
echo "    Modules: $MODOUT/lib/modules/$KREL"
echo
echo "Rebuild the rootfs with these modules:"
echo "    sudo MODULES_DIR=$MODOUT/lib/modules VER=<release> ./build-rootfs.sh"
